  const __nv_bfloat16* w_ptr =
      reinterpret_cast<const __nv_bfloat16*>(w_c.data_ptr<at::BFloat16>());
  __nv_bfloat16* y_ptr =
      reinterpret_cast<__nv_bfloat16*>(y.data_ptr<at::BFloat16>());

  conv3x3_bf16_kernel<<<grid, block, 0, at::cuda::getCurrentCUDAStream()>>>(
      x_ptr, w_ptr, y_ptr, (int)N, (int)H, (int)W, (int)Ho, (int)Wo);
  C10_CUDA_KERNEL_LAUNCH_CHECK();

  return y;
}
