    const __nv_bfloat16* __restrict__ w,
    __nv_bfloat16* __restrict__ y,
    const int N,
    const int H,
    const int W,
    const int Ho,
    const int Wo) {
  __shared__ __align__(4) __nv_bfloat16 xs[IN_C][SY][SX];
  __shared__ float ws[IN_C * K * K];

  const int tx = threadIdx.x;
  const int ty = threadIdx.y;
  const int tid = ty * blockDim.x + tx;

  const int ow0 = blockIdx.x * OT_X;
  const int oh0 = blockIdx.y * OT_Y;

  const int nz = blockIdx.z;
  const int n = nz / OUT_C;
  const int oc = nz % OUT_C;

  if (tid < IN_C * K * K) {
    ws[tid] = __bfloat162float(w[(size_t)oc * (IN_C * K * K) + tid]);
  }

  const size_t x_base = (size_t)n * IN_C * H * W;
  constexpr int TILE_ELEMS = IN_C * SY * SX;
  constexpr int THREADS = TILE_X * TILE_Y;

  for (int idx = tid; idx < TILE_ELEMS; idx += THREADS) {
    const int c = idx / (SY * SX);
    const int rem = idx % (SY * SX);
    const int yy = rem / SX;
    const int xx = rem % SX;

    const int ih = oh0 + yy;
    const int iw = ow0 + xx;

    __nv_bfloat16 v = __float2bfloat16(0.0f);
    if (ih >= 0 && ih < H && iw >= 0 && iw < W) {
      v = x[x_base + ((size_t)c * H + ih) * W + iw];
    }
    xs[c][yy][xx] = v;
  }

  __syncthreads();

  const int oh = oh0 + ty * RB_Y;
  const int ow = ow0 + tx * RB_X;
  float acc[RB_Y][RB_X];
  #pragma unroll
  for (int ry = 0; ry < RB_Y; ++ry) {
    #pragma unroll
    for (int rx = 0; rx < RB_X; ++rx) {
      acc[ry][rx] = 0.0f;
    }
  }
  #pragma unroll
  for (int c = 0; c < IN_C; ++c) {
    float patch[RB_Y + K - 1][RB_X + K - 1];
    #pragma unroll
    for (int py = 0; py < RB_Y + K - 1; ++py) {
      const __nv_bfloat16* row = &xs[c][ty * RB_Y + py][tx * RB_X];
      #pragma unroll
      for (int px = 0; px < RB_X + K - 1; px += 2) {
        const float2 f = __bfloat1622float2(*reinterpret_cast<const __nv_bfloat162*>(row + px));
        patch[py][px] = f.x;
        patch[py][px + 1] = f.y;
      }
    }
    #pragma unroll
    for (int ky = 0; ky < K; ++ky) {
      #pragma unroll
      for (int kx = 0; kx < K; ++kx) {
        const float wv = ws[c * 9 + ky * 3 + kx];
        #pragma unroll
        for (int ry = 0; ry < RB_Y; ++ry) {
          #pragma unroll
          for (int rx = 0; rx < RB_X; ++rx) {
            acc[ry][rx] = fmaf(patch[ky + ry][kx + rx], wv, acc[ry][rx]);
          }
        }
      }
    }
  }
  #pragma unroll
  for (int ry = 0; ry < RB_Y; ++ry) {
    const int ohh = oh + ry;
    if (ohh < Ho) {
      #pragma unroll
      for (int rx = 0; rx < RB_X; ++rx) {
        const int oww = ow + rx;
        if (oww < Wo) {
          y[(((size_t)n * OUT_C + oc) * Ho + ohh) * Wo + oww] = __float2bfloat16(acc[ry][rx]);
        }
      }
    }
  }
}

